+      prompt: text,
+      status: "draft",
+      workspace: { mode: "project", path: project.path },
+      run: null,
+      createdAt: timestamp,
+      updatedAt: timestamp
+    }
+    this.tasks.push(task)
+    await this.persist()
+    return structuredClone(task)
+  }
+}
